import RNA, random, multiprocessing as mp, time
target='.....((.((..(((((.(((....)))(((....)))))).....((((((....)))(((....))).)))))..)).)).....................'
def worker(seed):
    random.seed(seed)
    deadline=time.time()+170
    while time.time()<deadline:
        start=''.join(random.choice('ACGU') for _ in range(len(target)))
        seq, d = RNA.inverse_fold(start, target)
        if d==0:
            st=RNA.fold_compound(seq).mfe()[0]
            if st==target:
                return seq
    return None
if __name__=='__main__':
    with mp.Pool(64) as p:
        for r in p.imap_unordered(worker, range(640)):
            if r:
                print('SOLVED', r, flush=True)
                p.terminate(); break
EOF
